// =====================================================================
// replay_test.cpp -- replay REAL rig data through the real node core.
//
// Fixture: tests/host/rig_tour_fixture.h, generated by
// tools/extract_rig_fixture.py from data/serial/tour_20261121_172641.log
// (the 2026-11-21 hardware tour: PM1125H meter + G100 VFD, 215 [RAW]
// telemetry rows = the model's whole feature identity {fset, v, i, pf}).
//
// What "PC == node" means here: the SAME core sources run as on the
// ESP32 (whole SensorNodeApp on the Arduino stubs, -DMONITOR_COND_OBS =
// the deployed firmware era). Differences: 1 monitor step per fixture
// feed at 1 Hz like the rig, but each 2 s [RAW] snapshot is held for
// its two 1 Hz feed steps (the rig's 400 ms polls between prints are
// not captured); float arch x86 vs Xtensa. Timing constants, settle
// windows, bands and evidence math are the deployed values.
//
// The rig's tour failed at the speed_1 revisit: the transition's
// unsettled steps cleared the sticky hold, the first settled step was
// judged against the stopped-scale fit theta, and the alarm latched
// through the whole phase_loss stage. This test asserts the tour
// semantics on the REAL data:
//   P0 commission at stopped   -> no alarm, baseline registered
//   P1 speed_1 (new)           -> alarm, ask, auto-label, clear
//   P2 stopped (revisit)       -> quiet match, zero alarms
//   P3 speed_1 (revisit)       -> quiet match, ZERO alarms  <- regression
//   P4 phase_loss (new fault)  -> its own fresh alarm, ask, label, clear
// =====================================================================
#include <cassert>
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>
#include "node_runtime.h"
#include "rig_tour_fixture.h"

static constexpr FeatureInfo FEATS[4] = {
  {"fset", "Hz"}, {"v", "V"}, {"i", "A"}, {"pf", ""}};
static const FeatureProfile PROF = {"rig_replay", 4, FEATS};

class ReplaySensor : public ISensorNode {
public:
  long t0 = 0;                     // fake-ms when learning started ('s')

  bool begin() override { return true; }
  void poll() override { last_ok_ = millis(); }
  uint32_t pollPeriodMs() const override { return 400; }
  bool fresh() const override {
    return last_ok_ != 0 && millis() - last_ok_ < cfg::FRESH_WINDOW_MS;
  }
  uint32_t lastOkMs() const override { return last_ok_; }
  uint32_t failCount() const override { return 0; }
  const FeatureProfile& profile() const override { return PROF; }
  // Row is derived from the SIMULATED clock, not from call counts:
  // features() is called by both the telemetry print (2 s) and the
  // monitor feed (1 Hz) paths, and both must see the same snapshot.
  // The second 1 Hz feed inside a row's 2 s window interpolates toward
  // the next row: the machine's current is physically continuous, and a
  // hard held copy would fake calm (zero step delta) on wild rows - the
  // replay's coast-down rows then settle mid-transition and alarm.
  void features(float* out) const override {
    long row = rowNow();
    long nxt = (row + 1 < rigfix::N_ROWS) ? row + 1 : row;
    float frac = fracInRow();
    for (int f = 0; f < 4; ++f) {
      const float a[4] = {rigfix::ROWS[row].fset, rigfix::ROWS[row].v,
                          rigfix::ROWS[row].i,   rigfix::ROWS[row].pf};
      const float b[4] = {rigfix::ROWS[nxt].fset, rigfix::ROWS[nxt].v,
                          rigfix::ROWS[nxt].i,   rigfix::ROWS[nxt].pf};
      out[f] = a[f] + frac * (b[f] - a[f]);
    }
  }
  size_t logLine(char* out, size_t cap) override {
    const rigfix::Row& r = rigfix::ROWS[rowNow()];
    return snprintf(out, cap, "[G100] fset=%5.2f v=%6.1f i=%4.2f pf=%5.2f",
                    r.fset, r.v, r.i, r.pf);
  }
  long rowNow() const {
    long row = (long)(millis() - t0) / 2000;   // 1 [RAW] row = 2 s
    if (row < 0) row = 0;
    if (row >= rigfix::N_ROWS) row = rigfix::N_ROWS - 1;
    return row;
  }
  float fracInRow() const {
    long m = (long)(millis() - t0) % 2000;
    float frac = (float)m / 2000.0f;
    if (frac < 0) frac = 0;
    if (frac > 1) frac = 1;
    return frac;
  }
  int truthNow() const { return rigfix::ROWS[rowNow()].truth; }

private:
  uint32_t last_ok_ = 0;
};

struct Ev { long feed; int truth; std::string line; };

// incremental read-back of the app's own console capture
static std::vector<std::string> pumpConsole(FILE*& rd, long& rdpos) {
  std::vector<std::string> out;
  fflush(stdout);
  if (!rd) rd = fopen("/tmp/tinyrl_replay.log", "r");
  assert(rd);
  fseek(rd, rdpos, SEEK_SET);
  char buf[1024];
  while (fgets(buf, sizeof(buf), rd)) {
    std::string l(buf);
    while (!l.empty() && (l.back() == '\n' || l.back() == '\r')) l.pop_back();
    if (!l.empty()) out.push_back(l);
  }
  rdpos = ftell(rd);
  return out;
}

int main() {
  FILE* cap = freopen("/tmp/tinyrl_replay.log", "w", stdout);
  assert(cap);

  ReplaySensor sensor;
  SensorNodeApp app;
  NodeIdentity id{"rigreplay-01", "v1/Plant01/Area/Line/Station-01",
                  "ssid", "pass", "127.0.0.1", 1883};
  app.begin(sensor, id);

  Serial.feed("s\n");                        // commission at stopped (P0)
  g_host_millis += 100;
  app.tick();                                // 's' processed, learning starts
  sensor.t0 = (long)g_host_millis;

  FILE* rd = nullptr;
  long rdpos = 0;
  std::vector<Ev> alarms, clears, asks, labels;
  int last_dump_truth = -1;
  bool seen_truth[3] = {false, false, false};   // one label per new state:
                                                // re-asks of a learned state
                                                // stay pending, like the rig
                                                // tour left them
  long guard = 0;
  const long T_END = sensor.t0 + 2000L * rigfix::N_ROWS;

  // the stub clock advances ~13 ms per millis() call inside tick() plus
  // the explicit +100 here: ~200 fake-ms per loop, so the 1 Hz feed and
  // 2 s print gates fire at their deployed ratio
  while (g_host_millis <= (unsigned long)T_END) {
    g_host_millis += 100;
    app.tick();
    if (++guard > 2000000L) {
      fprintf(stderr, "REPLAY: simulated clock stalled at %lu\n",
              (unsigned long)g_host_millis);
      return 1;
    }
    int truth = sensor.truthNow();
    for (auto& l : pumpConsole(rd, rdpos)) {
      if (l.find("[RL] ALARM") != std::string::npos)
        alarms.push_back({sensor.rowNow(), truth, l});
      if (l.find("[RL] clear") != std::string::npos)
        clears.push_back({sensor.rowNow(), truth, l});
      // library dump at every truth boundary: shows the yardstick and
      // centroid evolution per phase
      if (truth != last_dump_truth) {
        last_dump_truth = truth;
        Serial.feed("l\n");
      }
      // label every ask with the tour plan's slug/kind for the CURRENT
      // truth - what rig_tour.py does at each prompt (2026-11-21 tour)
      const char* pend = strstr(l.c_str(), "[PEND] batch ");
      if (pend) {
        char bid[16] = "";
        if (sscanf(pend, "[PEND] batch %15s", bid) == 1) {
          asks.push_back({sensor.rowNow(), truth, l});
          if (!seen_truth[truth]) {
            seen_truth[truth] = true;
            char cmd[96];
            snprintf(cmd, sizeof(cmd), "f %s %s %s\n", bid,
                     rigfix::truthName(truth), rigfix::truthKind(truth));
            Serial.feed(cmd);
          }
        }
      }
      const char* fb = strstr(l.c_str(), "[FB] batch ");
      if (fb) labels.push_back({sensor.rowNow(), truth, l});
    }
  }
  if (rd) { fclose(rd); rd = nullptr; rdpos = 0; }

  // end-of-run vocabulary dump: the adapted yardsticks are the evidence
  // for the 7.3 lever (units grew toward the observed steady-state spread)
  Serial.feed("l\n");
  app.tick();
  for (auto& l : pumpConsole(rd, rdpos))
    if (l.find("[LIB]") != std::string::npos ||
        l.find("  ") == 0)
      fprintf(stderr, "LIBDUMP %s\n", l.c_str());

  // ---- per-phase verdicts ------------------------------------------------
  auto count = [](const std::vector<Ev>& v, int t) {
    int n = 0;
    for (auto& e : v) if (e.truth == t) ++n;
    return n;
  };
  const int a0 = count(alarms, 0), a1 = count(alarms, 1);
  const int a2 = count(alarms, 2);
  const int a0_after = a0;                    // truth 0 covers P0 AND P2
  (void)a0_after;
  bool labeled_speed1 = false, labeled_pl = false;
  for (auto& e : labels) {
    if (e.line.find("'speed_1'") != std::string::npos) labeled_speed1 = true;
    if (e.line.find("'speed_1_phase_loss'") != std::string::npos)
      labeled_pl = true;
  }
  // P1 clear: a clear attributed to truth 1 AFTER the speed_1 label
  bool p1_clear = false;
  long t_label1 = -1;
  for (auto& e : labels)
    if (labeled_speed1 && e.line.find("'speed_1'") != std::string::npos)
      t_label1 = e.feed;
  for (auto& e : clears)
    if (t_label1 >= 0 && e.truth == 1 && e.feed > t_label1) p1_clear = true;
  bool p4_clear = false;
  long t_label4 = -1;
  for (auto& e : labels)
    if (e.line.find("'speed_1_phase_loss'") != std::string::npos)
      t_label4 = e.feed;
  for (auto& e : clears)
    if (t_label4 >= 0 && e.truth == 2 && e.feed > t_label4) p4_clear = true;

  fprintf(stderr,
          "REPLAY alarms by truth: stopped=%d speed_1=%d phase_loss=%d"
          " | asks=%zu labels=%zu (speed_1=%d phase_loss=%d)"
          " | clears=%zu (after speed_1 label: %s, after fault label: %s)\n",
          a0, a1, a2, asks.size(), labels.size(),
          labeled_speed1, labeled_pl, clears.size(),
          p1_clear ? "yes" : "NO", p4_clear ? "yes" : "NO");

  // The tour semantics on real data. truth 0 spans P0 (commission) and
  // P2 (revisit): both must be silent. truth 1 spans P1 (new: the one
  // honest alarm) and P3 (revisit: silent - the 2026-11-21 rig failure).
  bool ok = true;
  auto check = [&](bool cond, const char* what) {
    if (!cond) { fprintf(stderr, "REPLAY FAIL: %s\n", what); ok = false; }
  };
  check(a0 == 0, "alarm fired on op_stopped (commission or revisit)");
  check(a2 == 1, "phase_loss did not earn exactly one fresh alarm");
  check(a1 == 1, "speed_1 alarms != 1: the NEW state must alarm once and"
                 " the REVISIT must stay quiet (rig failure mode)");
  check(labeled_speed1, "no speed_1 batch label");
  check(labeled_pl, "no speed_1_phase_loss batch label");
  check(p1_clear, "no clear after the speed_1 label");
  check(p4_clear, "no clear after the phase_loss label");
  if (!ok) return 1;

  fprintf(stderr, "REPLAYCHECK OK: rig tour replays clean - commission"
                  " quiet, new-state alarm+label, revisits quiet, fault"
                  " alarms once and clears\n");
  return 0;
}
